INSERT INTO public.products (id, confectioner_id, category_id, slug, title, description, long_description, price, old_price, weight_grams, servings, tags, dietary_features, status, is_featured, views_count, sales_count, rating_average, reviews_count, published_at)
VALUES
  ('aaaaaaaa-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111101', (SELECT id FROM public.product_categories WHERE slug='cakes'), 'svadebnyy-tort-yagodnyy-barhat', 'Свадебный торт «Ягодный бархат»', 'Трёхъярусный торт с муссом из красных ягод и бархатными коржами', 'Нежные бархатные коржи, крем-чиз на сливках, прослойка из малины и клубники. Оформление живыми цветами (съедобные).', 18500, 21000, 5500, 35, ARRAY['свадебный','ягодный','мусс'], ARRAY['без консервантов']::text[], 'published', true, 1240, 32, 5.0, 12, now()),
  ('aaaaaaaa-0000-4000-8000-000000000002', '11111111-1111-4111-8111-111111111101', (SELECT id FROM public.product_categories WHERE slug='cakes'), 'tort-napoleon-domashniy', 'Домашний «Наполеон»', '24 коржа, заварной крем на настоящей ванили', 'Классический наполеон: тончайшие коржи, насыщенный заварной крем, ваниль Мадагаскар. Готовим за сутки — пропитка идеальная.', 2400, NULL, 1600, 12, ARRAY['наполеон','классика'], ARRAY['содержит глютен','молочные продукты']::text[], 'published', false, 860, 54, 4.9, 21, now()),
  ('aaaaaaaa-0000-4000-8000-000000000003', '11111111-1111-4111-8111-111111111101', (SELECT id FROM public.product_categories WHERE slug='bento'), 'bento-tort-nezhnyy', 'Бенто-торт «Нежность»', 'Мини-торт 10 см на двоих — идеальный подарок', 'Бенто-торт с надписью на выбор: порционный, аккуратный, в крафт-коробке с ложечкой.', 1200, 1400, 450, 2, ARRAY['бенто','подарок'], ARRAY[]::text[], 'published', true, 2100, 96, 4.8, 40, now()),
  ('aaaaaaaa-0000-4000-8000-000000000004', '11111111-1111-4111-8111-111111111102', (SELECT id FROM public.product_categories WHERE slug='cupcakes'), 'kapkeyki-vanilnyye-12', 'Капкейки ванильные (12 шт.)', 'Ванильные капкейки с шапочкой крем-чиз', 'Нежная ванильная крошка, стабильный крем-чиз, декор по теме праздника.', 1900, NULL, 1100, 12, ARRAY['капкейки','детский'], ARRAY[]::text[], 'published', false, 700, 71, 4.7, 18, now()),
  ('aaaaaaaa-0000-4000-8000-000000000005', '11111111-1111-4111-8111-111111111102', (SELECT id FROM public.product_categories WHERE slug='macarons'), 'makarons-assorti-15', 'Макаронс ассорти (15 шт.)', '15 вкусов в одной коробке: от фисташки до солёной карамели', 'Классические миндальные макаронс ручной работы. Коробка крафт с лентой.', 2600, 2900, 700, 15, ARRAY['макаронс','десерт'], ARRAY['содержит орехи']::text[], 'published', true, 1900, 88, 4.9, 33, now()),
  ('aaaaaaaa-0000-4000-8000-000000000006', '11111111-1111-4111-8111-111111111102', (SELECT id FROM public.product_categories WHERE slug='gingerbread'), 'pryaniki-rospis-9', 'Имбирные пряники с росписью (9 шт.)', 'Пряники ручной росписи — любой сюжет', 'Медовые пряники с глазурной росписью: имена, даты, персонажи. Срок — 3 дня.', 1500, NULL, 600, 9, ARRAY['пряники','роспись','подарок'], ARRAY['содержит глютен']::text[], 'published', false, 1100, 120, 4.8, 47, now()),
  ('aaaaaaaa-0000-4000-8000-000000000007', '11111111-1111-4111-8111-111111111103', (SELECT id FROM public.product_categories WHERE slug='realistic_cakes'), 'tort-korovka-3d', '3D-торт «Коровка»', 'Реалистичный торт-скульптура — раскрасит любой праздник', 'Полностью съедобная скульптура на основе риc-криспис и мастики. Диаметр 25 см.', 6500, NULL, 2800, 15, ARRAY['3d','детский','реалистичный'], ARRAY[]::text[], 'published', true, 3300, 41, 5.0, 26, now()),
  ('aaaaaaaa-0000-4000-8000-000000000008', '11111111-1111-4111-8111-111111111103', (SELECT id FROM public.product_categories WHERE slug='zephyr_bouquets'), 'buquet-zeefirnyy', 'Зефирный букет «Пион»', 'Букет из зефира ручной посадки — съедобная альтернатива цветам', '12 зефирных «пионов» на шпажках в крафтовой обёртке. Хранится 5 дней.', 3200, 3600, 900, 12, ARRAY['зефир','букет','подарок'], ARRAY['без глютена']::text[], 'published', false, 1500, 63, 4.9, 29, now()),
  ('aaaaaaaa-0000-4000-8000-000000000009', '11111111-1111-4111-8111-111111111101', (SELECT id FROM public.product_categories WHERE slug='pastila'), 'pastila-yabloko-bez-sahara', 'Пастила яблочная без сахара (200 г)', 'Только яблоки — 100% фруктовая пастила', 'Сушка при 55°C сохраняет витамины. Без сахара, глютена и консервантов.', 690, NULL, 200, 4, ARRAY['пастила','пп'], ARRAY['без сахара','без глютена','веган']::text[], 'published', false, 900, 140, 4.7, 52, now()),
  ('aaaaaaaa-0000-4000-8000-00000000000a', '11111111-1111-4111-8111-111111111102', (SELECT id FROM public.product_categories WHERE slug='chocolate'), 'chokolatnyy-candy-bar', 'Кэнди-бар шоколадный (30 персон)', 'Шоколадные конфеты ручной работы для кэнди-бара', 'Ассорти из 6 видов конфет: трюфели, пралине, карамель, женьшень.', 5900, NULL, 1800, 30, ARRAY['шоколад','кэнди-бар'], ARRAY['содержит орехи']::text[], 'published', false, 640, 22, 4.8, 14, now()),
  ('aaaaaaaa-0000-4000-8000-00000000000b', '11111111-1111-4111-8111-111111111103', (SELECT id FROM public.product_categories WHERE slug='desserts'), 'deserty-portSIONnyye-20', 'Порционные десерты (20 шт.)', 'Набор муссовых десертов для фуршета', '20 порций: тирамису, панна-котта, чизкейк, малиновый мусс. В индивидуальных стаканах.', 4400, 4900, 2200, 20, ARRAY['десерты','фуршет'], ARRAY[]::text[], 'published', true, 1750, 58, 4.9, 31, now()),
  ('aaaaaaaa-0000-4000-8000-00000000000c', '11111111-1111-4111-8111-111111111103', (SELECT id FROM public.product_categories WHERE slug='lollipops'), 'lollipop-candy-bar-25', 'Леденцы на палочках (25 шт.)', 'Яркие леденцы ручной тяги для детского праздника', 'Натуральные красители, индивидуальная упаковка с этикеткой.', 2500, NULL, 900, 25, ARRAY['леденцы','детский'], ARRAY[]::text[], 'published', false, 800, 90, 4.6, 25, now())
