VALUES
  ('bbbbbbbb-0000-4000-8000-000000000001', '11111111-1111-4111-8111-111111111104', 'Лофт «Восток»', 'Просторный лофт с панорамными окнами и профессиональной кухней — идеален для свадеб и корпоративов.', 'г. Москва, ул. Восточная, 15, 2 этаж', 'Москва', 'Москва', 80, 350000, 3, ARRAY['https://images.unsplash.com/photo-1519167758481-83f550bb49b3?w=800','https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?w=800'], ARRAY['kitchen','sound','parking','wifi','projector'], '{"phone":"+7 495 123-45-67","telegram":"@loftvostok"}', 'Курение запрещено. Шумные мероприятия до 23:00. Депозит 50%.', true, true, 4.9, 27, 63),
  ('bbbbbbbb-0000-4000-8000-000000000002', '11111111-1111-4111-8111-111111111104', 'Банкетный зал «Уездная усадьба»', 'Зал в стиле дореволюционной усадьбы: лепнина, хрусталь, камин. Авторская сервировка.', 'г. Волоколамск, ул. Усадебная, 3', 'Волоколамск', 'Московская область', 60, 250000, 4, ARRAY['https://images.unsplash.com/photo-1519671482749-fd09be7ccebf?w=800'], ARRAY['fireplace','sound','parking','wardrobe'], '{"phone":"+7 496 111-22-33"}', 'Фуршет от кейтеринга площадки или согласованных партнёров.', true, true, 4.8, 19, 41),
  ('bbbbbbbb-0000-4000-8000-000000000003', '11111111-1111-4111-8111-111111111104', 'Детская студия «Сладкий город»', 'Яркая студия для детских праздников: игровая зона, аниматоры, сладкий стол.', 'г. Москва, Ленинский пр-т, 88', 'Москва', 'Москва', 30, 180000, 2, ARRAY['https://images.unsplash.com/photo-1513889961551-628c1e5e2ee9?w=800'], ARRAY['kids_zone','sound','parking','wifi'], '{"phone":"+7 495 777-88-99","telegram":"@sweetcity"}', 'Дети — только в сопровождении взрослых. Аниматоры — по договорённости.', true, true, 4.7, 34, 87),
  ('bbbbbbbb-0000-4000-8000-000000000004', '11111111-1111-4111-8111-111111111104', 'Терраса «Закат»', 'Летняя терраса с видом на реку: живая музыка, гирлянды, открытая кухня.', 'г. Казань, ул. Речная, 7', 'Казань', 'Татарстан', 50, 220000, 3, ARRAY['https://images.unsplash.com/photo-1470337458703-46ad1756a187?w=800'], ARRAY['terrace','grill','sound','parking'], '{"phone":"+7 843 222-33-44"}', 'Сезон: май–сентябрь. Резерв от 3 часов.', true, false, 4.6, 12, 23)
